mapper.update:
update hr_emp_image
image_type = #{image_type}, ability_score = #{ability_score}, tech_ability = #{tech_ability}, workload_ability = #{workload_ability}, quality_ability = #{quality_ability}, contribution_ability = #{contribution_ability}, stability_ability = #{stability_ability}, performance_trend = #{performance_trend}, learning_ability = #{learning_ability}, growth_speed = #{growth_speed}, incentive_response = #{incentive_response}, promotion_probability = #{promotion_probability}, retention_risk = #{retention_risk}, performance_level = #{performance_level}, skill_tags = #{skill_tags}, work_style = #{work_style}, career_orientation = #{career_orientation}, risk_level = #{risk_level}, model_version = #{model_version}, updated_time = now()
