mapper.select:
select ei.id, ei.staff_id, ei.image_type, ei.ability_score, ei.performance_level, COALESCE(ei.skill_tags, s.skill_tags) as skill_tags, ei.work_style, ei.career_orientation, ei.risk_level, ei.model_version, ei.status, ei.created_time, ei.updated_time, ei.tech_ability, ei.workload_ability, ei.quality_ability, ei.contribution_ability, ei.stability_ability, ei.performance_trend, ei.learning_ability, ei.growth_speed, ei.incentive_response, ei.promotion_probability, ei.retention_risk, s.sname, s.sid, DATE_FORMAT(ei.created_time,'%Y-%m-%d %H:%i:%s') as created_time1, DATE_FORMAT(ei.updated_time,'%Y-%m-%d %H:%i:%s') as updated_time1 from hr_emp_image ei left join hr_employee s on ei.staff_id = s.id where (ei.status = 1 or ei.status is null)
and ei.image_type = #{image_type}
order by ei.created_time desc limit #{startIndex}, #{pageSize}

select ei.id, ei.staff_id, ei.image_type, ei.ability_score, ei.performance_level, COALESCE(ei.skill_tags, s.skill_tags) as skill_tags, ei.work_style, ei.career_orientation, ei.risk_level, ei.model_version, ei.status, ei.created_time, ei.updated_time, ei.tech_ability, ei.workload_ability, ei.quality_ability, ei.contribution_ability, ei.stability_ability, ei.performance_trend, ei.learning_ability, ei.growth_speed, ei.incentive_response, ei.promotion_probability, ei.retention_risk, s.sname, s.sid, DATE_FORMAT(ei.created_time,'%Y-%m-%d %H:%i:%s') as created_time1, DATE_FORMAT(ei.updated_time,'%Y-%m-%d %H:%i:%s') as updated_time1 from hr_emp_image ei left join hr_employee s on ei.staff_id = s.id where (ei.status = 1 or ei.status is null)
and ei.staff_id = #{staff_id}
and ei.image_type = #{image_type}
and s.sname like concat('%',#{sname},'%')
and ei.performance_level = #{performance_level}
order by ei.created_time desc limit #{startIndex}, #{pageSize}

mapper.update:
